// regra — laço dos jobs longos: Wait 15 s → GET /jobs/{id} enquanto `queued` OU `running`
// (api/rotas_jobs.py:13-16; api/jobs.py:18-20 — sucesso é `done`, não `ok`), máx. 160 voltas = 40 min (plano §5 W22 passo 2; eram 45 = 675 s — em 26/09 a leitura de Lapa/PR levou 776 s e a de Massaranduba/SC 881 s, e o W22 desistia com o texto quase pronto).
// Worker sem resposta numa volta (reinício) não mata o laço: conta a volta e pergunta de novo.
const MAX = 160;
const r = $input.first().json || {};
const volta = $runIndex + 1;
const jobId = $('POST /jobs/paginas').first().json.body.job_id;
const b = (r.body && typeof r.body === 'object') ? r.body : {};
let status;
if (r.error) status = 'sem_resposta';
else if (r.statusCode !== 200) status = 'http_' + r.statusCode;
else status = String(b.status || 'desconhecido');
const ativo = status === 'queued' || status === 'running' || status === 'sem_resposta';
let motivo = null;
if (status === 'error') {
  const e = b.erro || {};
  motivo = `job ${jobId} falhou: ${e.tipo || 'erro'}: ${String(e.mensagem || '').slice(0, 300)}`;
} else if (ativo && volta >= MAX) {
  motivo = `job ${jobId} não terminou em ${MAX} voltas de 15 s (último status: ${status})`;
} else if (!ativo && status !== 'done') {
  motivo = `GET /jobs/${jobId} respondeu ${status}`;
}
return [{ json: {
  job_id: jobId, volta, status,
  continuar_esperando: ativo && volta < MAX,
  concluido: status === 'done',
  result: status === 'done' ? (b.result || {}) : null,
  progresso: b.progresso ?? null,
  motivo,
} }];

// O worker gravou leituras + paginas numa transação só e já marcou a vigente (api/leitura.py:170-199).
// Aqui só se lê o resultado: {leitura_id, n_paginas, chars_total, modo_sugerido, condicoes, assinatura_conjunto, versao_ocr}.
const res = $json.result || {};
const cond = res.condicoes || {};
return [{ json: {
  job_id: $json.job_id,
  leitura_id: res.leitura_id ?? null,
  n_paginas: res.n_paginas || 0,
  chars_total: res.chars_total || 0,
  modo_sugerido: res.modo_sugerido ?? null,
  versao_ocr: res.versao_ocr ?? null,
  assinatura_conjunto: res.assinatura_conjunto ?? null,
  reusada: res.reusada === true,
  segundos: res.segundos ?? null,
  paginas_ocr: cond.paginas_ocr || 0,
  arquivos_ocr: cond.arquivos_ocr || [],
  furtivos: cond.furtivos || [],
  // o que o worker classificou como cara de instrução para IA (api/injecao.py): é deles o aviso
  furtivos_suspeitos: res.furtivos_suspeitos ?? null,
  furtivos_suspeitos_textos: res.furtivos_suspeitos_textos || [],
  nao_pdf: cond.nao_pdf || [],
} }];

return [{ json: { ok: true, continuar: false, estado: 'sem_pdf_legivel',
  controle: $('Chamado pelo W20').first().json.controle,
  motivo: 'nenhuma página legível', job_id: $('Leitura').first().json.job_id } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const site = String($env.FOPA_SITE_PUBLIC_URL || '').replace(/\/+$/, '');
const n8nBase = String($env.WEBHOOK_URL || '').replace(/\/+$/, '');
const linkExecucao = `${n8nBase}/workflow/${$workflow.id}/executions/${$execution.id}`;
// regra — texto furtivo (branco/minúsculo/fora da página) visto ANTES do modelo: vira tag "Prompt Injection -
// Conteúdo Suspeito" na verificação (scripts/fopa/furtivo.py; T4/T5 do 40_fumaca.py) e aviso na fila (plano §5 W22 passo 6)
const lic = $('Transição → lendo').first().json;
const l = $('Leitura').first().json;
const onde = `${lic.municipio || lic.orgao || lic.controle}/${lic.uf || '—'}`;
// 25/09: só o texto escondido com cara de instrução para IA vira aviso (o timbre branco e a camada de OCR não)
const lista = (l.furtivos_suspeitos_textos && l.furtivos_suspeitos_textos.length) ? l.furtivos_suspeitos_textos : l.furtivos;
const itens = lista.slice(0, 20).map((f) => '<li>' + esc(typeof f === 'string' ? f : JSON.stringify(f)).slice(0, 300) + '</li>').join('');
return [{ json: {
  controle: lic.controle,
  assunto: `[FOPA] Texto furtivo antes do modelo: ${onde}`,
  corpo_html: `<p>A leitura ${esc(l.leitura_id)} de <b>${esc(lic.orgao || '')}</b> (${esc(onde)}, controle ${esc(lic.controle)}) `
    + `tem ${lista.length} trecho(s) de texto escondido com cara de instrução para IA. A extração segue; a verificação sai com a tag de injeção e revisão humana.</p>`
    + `<ul>${itens}</ul>`
    + `<p><a href="${esc(site)}/licitacao/${esc(lic.slug)}">Abrir no site</a> · <a href="${esc(linkExecucao)}">execução ${esc($execution.id)}</a></p>`,
} }];

const l = $('Leitura').first().json;
// db/032: sem provedor real, a licitação real para em preparada (a fila das 6h baixa e lê; extrai quando houver IA real)
const jevRodou = (() => { try { return $('Jev: interpretar o escopo (worker)').isExecuted; } catch (e) { return false; } })();
const jevEdital = jevRodou ? (($('Jev: interpretar o escopo (worker)').first().json.body) || {}).p_sim ?? null : null;
const extrair = $('Conferir leitura vigente').first().json.extrair_agora !== false;
return [{ json: { ok: true, continuar: extrair, estado: 'preparada',
  controle: $('Chamado pelo W20').first().json.controle,
  motivo: `W22: ${l.n_paginas} página(s), leitura ${l.leitura_id}${l.reusada ? ' (reusada)' : ''}` + (extrair ? '' : ' — a extração espera o provedor real (db/032)'),
  leitura_id: l.leitura_id, n_paginas: l.n_paginas, chars_total: l.chars_total, modo_sugerido: l.modo_sugerido,
  paginas_ocr: l.paginas_ocr, furtivos: l.furtivos.length, reusada: l.reusada, job_id: l.job_id,
  // a nota do Jev COM O EDITAL (db/035): a trava da IA na vaga do W23 decide com ela e a só-objeto
  jev_edital: jevEdital } }];

// Falha vira MOTIVO escrito (fica em licitacao_eventos e no retorno para o W20), nunca silêncio.
// Aceita o item de qualquer ramo que falhou: HTTP com erro de rede, HTTP com status ruim, laço esgotado.
const j = $input.first().json || {};
let motivo = j.motivo || j.falha || null;
if (!motivo && j.error) {
  motivo = 'sem resposta (rede/timeout): ' + String(j.error.message || j.error.description || JSON.stringify(j.error)).slice(0, 240);
}
if (!motivo && j.statusCode) {
  const corpo = typeof j.body === 'string' ? j.body : JSON.stringify(j.body ?? '');
  motivo = `HTTP ${j.statusCode}: ${corpo.slice(0, 300)}`;
}
return [{ json: { motivo: 'W22: ' + (motivo || 'falha sem motivo declarado') } }];

return [{ json: { ok: false, continuar: false, estado: 'erro_leitura',
  controle: $('Chamado pelo W20').first().json.controle,
  motivo: $('Motivo da falha').first().json.motivo } }];

// regra — o escopo com o EDITAL (73_: objeto + as páginas da leitura com mais termos da pergunta) logo depois
// da leitura: é a nota que a trava da IA espera (db/035; a só-objeto tem o ponto cego do credenciamento).
// O Jev é SINAL (T25): falhar aqui não para a leitura — api/rotas_jev.py:33-62
const b = $input.first().json.body;
return b.requisicoes.slice(0, 1).map((r) => ({ json: { url: b.url, body: r.body, controle: r.controle,
  regra_dentro: r.regra_dentro === true, contexto_enviado: r.contexto_enviado } }));
